static void FABLE_NATIVE_THISCALL yieldSlot2(CAIBrain* brain)
{
    if (brain != expectedBrain) yieldWrongBrain = 1;
    ++yields;
    if (brainAfterYield) { activeGroup->PBrain=brainAfterYield; expectedBrain=brainAfterYield; brainAfterYield=0; }
}

static void addEvent(SMessageNode* node, fable_i32 type, fable_u32 uid0, fable_u32 uid1)
{
    memset(node, 0, sizeof(*node));
    node->Event.Type = type;
    node->Event.OriginatorUID[0] = uid0;
    node->Event.OriginatorUID[1] = uid1;
}

static void linkList(SMessageNode* head, SMessageNode* nodes, int count)
{
    int i;
    head->next = count ? &nodes[0] : head;
    head->prev = count ? &nodes[count - 1] : head;
    for (i = 0; i < count; ++i) {
        nodes[i].prev = i ? &nodes[i - 1] : head;
        nodes[i].next = i + 1 < count ? &nodes[i + 1] : head;
    }
}

static void initTest(CAIStateGroupBaseAccess* group, CAIBrain* brain,
                     const long* values, int count)
{
    int i;
    memset(&worldA, 0, sizeof(worldA));
    memset(&worldB, 0, sizeof(worldB));
    memset(&managerA, 0, sizeof(managerA));
    memset(&managerB, 0, sizeof(managerB));
    worldA.PMessageEventManager_Data = &managerA;
    worldB.PMessageEventManager_Data = &managerB;
    managerA.World = &worldA;
    managerB.World = &worldB;
    memset(brainVtable, 0, sizeof(brainVtable));
    brainVtable[2] = (void*)&yieldSlot2;
    brain->__vftable = brainVtable;
    group->PBrain = brain;
    expectedBrain = brain; activeGroup=group; brainAfterYield=0;
    stopped = stopOnCheck = stoppingChecks = 0;
    worldCalls = worldRotation = 0;
    tickCount = count;
    tickCalls = badWorldBeforeTick = lastOperationWasWorld = 0;
    yields = yieldWrongBrain = 0;
    managerQueries = badManager = 0;
    typeCalls = originatorCalls = badOriginator = 0;
    expectedOriginator = 0;
    expectedUID[0] = expectedUID[1] = 0;
    mutateSentinelOnType = 0;
    managerResult = expectedResult = 0;
    for (i = 0; i < count; ++i) tickValues[i] = values[i];
}

bool CAIStateGroupBaseAccess::IsStopping()
{
    ++stoppingChecks;
    return stopped || (stopOnCheck && stoppingChecks >= stopOnCheck);
}

CWorld* CAIStateGroupBaseAccess::GetPWorld()
{
    ++worldCalls;
    lastOperationWasWorld = 1;
    return (worldRotation++ & 1) ? &worldB : &worldA;
}

long FABLE_FASTCALL GetGameTick()
{
    int i = tickCalls++;
    if (!lastOperationWasWorld) badWorldBeforeTick = 1;
    lastOperationWasWorld = 0;
    if (!tickCount) return 0;
    return tickValues[i < tickCount ? i : tickCount - 1];
}

bool CMessageEventFilter_IsOfType::operator()(CMessageEvent* event) const
{
    int i = typeCalls++;
    if (i < 16) {
        typeValues[i] = Type;
        eventTypeValues[i] = event->Type;
    }
    if (mutateSentinelOnType && typeCalls == 1) {
        managerA.Messages = mutateSentinelOnType;
        managerB.Messages = mutateSentinelOnType;
    }
    return event && event->Type == Type;
}

CMessageEventFilter_IsOriginatedByThing::CMessageEventFilter_IsOriginatedByThing(
    const CThingCreatureBase* thing)
{
    if (thing != expectedOriginator) badOriginator = 1;
    // Actual constructor006AF290 reads the native CThing UID words at18/1c;
    // these inherited words are opaque named arrays in the actual creature header.
    memcpy(&UID[0], thing->_pad_0x18, sizeof(fable_u32));
    memcpy(&UID[1], thing->_pad_0x1c, sizeof(fable_u32));
}

bool CMessageEventFilter_IsOriginatedByThing::operator()(CMessageEvent* event) const
{
    ++originatorCalls;
    return event && event->OriginatorUID[0] == UID[0] && event->OriginatorUID[1] == UID[1];
}

CMessageEvent* CMessageEventManager::FindMostRecentMessage(const COwnMessageFilter& filter)
{
    SMessageNode* head = Messages;
    SMessageNode* node;
    ++managerQueries;
    if ((this != &managerA && this != &managerB) || !filter.TypeFilter || !filter.OriginatorFilter)
        badManager = 1;
    node = head->next;
    while (node != head) {
        CMessageEvent* event = &node->Event;
        if ((*filter.TypeFilter)(event) && (*filter.OriginatorFilter)(event)) {
            managerResult = event;
            return event;
        }
        node = node->next;
        head = Messages;
    }
    return 0;
}

