    CAIStateGroupBaseAccess group;
    CAIBrain brain;
    CThingCreatureBase originator;
    SMessageNode head, nodes[3], replacementHead;
    long ticks[4];

    memset(&group, 0, sizeof(group));
    memset(&brain, 0, sizeof(brain));
    memset(&originator, 0, sizeof(originator));
    ticks[0] = ticks[1] = 5;
    initTest(&group, &brain, ticks, 2);
    stopped = 1;
    if (group.AIAction_WaitForMessage(E_MESSAGE_EVENT_TYPE_TEST, 0, 4) != AI_ACTION_RETURN_ONE ||
        stoppingChecks != 1 || worldCalls || tickCalls || yields)
        return fail("initial stopping short-circuits before world, clock, and yield");

    ticks[0] = ticks[1] = 10;
    initTest(&group, &brain, ticks, 2);
    if (group.AIAction_WaitForMessage(E_MESSAGE_EVENT_TYPE_TEST, 0, -1) != AI_ACTION_RETURN_THREE ||
        worldCalls != 2 || tickCalls != 2 || yields || badWorldBeforeTick)
        return fail("initial deadline uses signed timeout and fetches world before both ticks");

    ticks[0] = ticks[1] = 100;
    initTest(&group, &brain, ticks, 2);
    memset(&head, 0, sizeof(head));
    addEvent(&nodes[0], E_MESSAGE_EVENT_TYPE_OTHER, 0, 0);
    addEvent(&nodes[1], E_MESSAGE_EVENT_TYPE_TEST, 0x1234, 0x5678);
    linkList(&head, nodes, 2);
    managerA.Messages = &head;
    managerB.Messages = &head;
    if (group.AIAction_WaitForMessage(E_MESSAGE_EVENT_TYPE_TEST, 0, 0) != AI_ACTION_RETURN_TWO ||
        yields != 1 || tickCalls != 2 || typeCalls != 2 || badWorldBeforeTick || yieldWrongBrain)
        return fail("null-originator path scans by type after yield and accepts at deadline equality");
    if (eventTypeValues[0] != E_MESSAGE_EVENT_TYPE_OTHER ||
        eventTypeValues[1] != E_MESSAGE_EVENT_TYPE_TEST ||
        typeValues[0] != E_MESSAGE_EVENT_TYPE_TEST || typeValues[1] != E_MESSAGE_EVENT_TYPE_TEST)
        return fail("null-originator walk applies requested type to each node in list order");

    ticks[0] = ticks[1] = 30;
    initTest(&group, &brain, ticks, 2);
    expectedOriginator = &originator;
    expectedUID[0] = 0x1234;
    expectedUID[1] = 0x5678;
    memcpy(originator._pad_0x18,&expectedUID[0],sizeof(fable_u32));
    memcpy(originator._pad_0x1c,&expectedUID[1],sizeof(fable_u32));
    memset(&head, 0, sizeof(head));
    addEvent(&nodes[0], E_MESSAGE_EVENT_TYPE_TEST, 0x1234, 0xaaaa);
    addEvent(&nodes[1], E_MESSAGE_EVENT_TYPE_OTHER, 0x1234, 0x5678);
    addEvent(&nodes[2], E_MESSAGE_EVENT_TYPE_TEST, 0x1234, 0x5678);
    linkList(&head, nodes, 3);
    managerA.Messages = &head;
    managerB.Messages = &head;
    expectedResult = &nodes[2].Event;
    if (group.AIAction_WaitForMessage(E_MESSAGE_EVENT_TYPE_TEST, &originator, 3) != AI_ACTION_RETURN_TWO ||
        yields != 1 || managerQueries != 1 || badManager || badOriginator ||
        managerResult != expectedResult || typeCalls != 3 || originatorCalls != 2)
        return fail("non-null originator passes type then UID filters and returns newest match");

    ticks[0] = 50; ticks[1] = 50; ticks[2] = 51;
    initTest(&group, &brain, ticks, 3);
    memset(&head, 0, sizeof(head));
    memset(&replacementHead, 0, sizeof(replacementHead));
    addEvent(&nodes[0], E_MESSAGE_EVENT_TYPE_OTHER, 0, 0);
    head.next = &nodes[0];
    head.prev = &nodes[0];
    nodes[0].prev = &head;
    nodes[0].next = &replacementHead;
    replacementHead.next = &replacementHead;
    replacementHead.prev = &replacementHead;
    managerA.Messages = &head;
    managerB.Messages = &head;
    mutateSentinelOnType = &replacementHead;
    if (group.AIAction_WaitForMessage(E_MESSAGE_EVENT_TYPE_TEST, 0, 0) != AI_ACTION_RETURN_THREE ||
        yields != 1 || typeCalls != 1 || tickCalls != 3 || worldCalls != 4 || badWorldBeforeTick)
        return fail("null-originator list reloads the manager sentinel after predicate and refreshes world before bottom tick");

    ticks[0] = ticks[1] = 60;
    initTest(&group, &brain, ticks, 2);
    stopOnCheck = 2;
    if (group.AIAction_WaitForMessage(E_MESSAGE_EVENT_TYPE_TEST, 0, 10) != AI_ACTION_RETURN_ONE ||
        stoppingChecks != 2 || yields != 1 || managerQueries || typeCalls || worldCalls != 2 ||
        tickCalls != 2 || badWorldBeforeTick)
        return fail("stopping after slot-2 yield returns before message scan and bottom tick");

    ticks[0]=10;ticks[1]=10;ticks[2]=10;ticks[3]=11;
    initTest(&group,&brain,ticks,4);
    CAIBrain replacementBrain; memset(&replacementBrain,0,sizeof(replacementBrain)); replacementBrain.__vftable=brainVtable;
    brainAfterYield=&replacementBrain;
    memset(&head,0,sizeof(head));head.next=head.prev=&head;
    managerA.Messages=managerB.Messages=&head;
    if(group.AIAction_WaitForMessage(E_MESSAGE_EVENT_TYPE_TEST,0,0)!=AI_ACTION_RETURN_THREE ||
       yields!=2 || yieldWrongBrain || group.PBrain!=&replacementBrain || tickCalls!=4 || worldCalls!=6 || badWorldBeforeTick)
        return fail("yield callback replaces brain and each later tick uses freshly fetched world");
    printf("0097d360_TEST PASS\n");
